import requests
import os
from app import util
BASE = os.getenv("BASE_URL", "https://api.example.com")
class Client:
    def get(self, id):
        return self._call(id)
    def _call(self, id):
        return requests.get(f"https://api.github.com/users/{id}").json()
def fetch_user(id):
    return Client().get(id)
def never_used():
    util.helper()
def recursive(n):
    return recursive(n - 1) if n else 0

